    @Test
    void tourismTaxListsPaidReservationsStartingInTheMonth() {
        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 4));

        // reservation 1: 1 guest, 2 nights = 9.00
        // reservation 3: 1 guest, 2 nights = 9.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-04
                reservation,room,check_in,check_out,guests,nights,tax
                1,201,2027-04-01,2027-04-03,1,2,9.00
                3,301,2027-04-02,2027-04-04,1,2,9.00
                total,18.00
                """, csv);
    }

    @Test
    void tourismTaxCalculatesCorrectlyForMultipleGuests() {
        Reservation july = book(201, "2027-07-10", "2027-07-13", RatePlan.STANDARD);
        NewReservation multiGuest = new NewReservation(
                201,
                new Guest("Ana Silva", "ana@example.com", "123.456.789-00"),
                LocalDate.parse("2027-07-10"),
                LocalDate.parse("2027-07-13"),
                2,
                RatePlan.STANDARD);
        Reservation withTwoGuests = service.create(multiGuest);
        service.confirm(withTwoGuests.id());

        String csv = new TourismTaxReport(store).generate(YearMonth.of(2027, 7));

        // 2 guests, 3 nights = 27.00
        assertEquals("""
                Pousada Maré Alta,tourism-tax,2027-07
                reservation,room,check_in,check_out,guests,nights,tax
                7,201,2027-07-10,2027-07-13,2,3,27.00
                total,27.00
                """, csv);
    }

    @Test
    void ratePlansShowsRevenueByPlan() {
        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 4));

        // STANDARD: reservation 1 (779.80) and 3 (1159.80) = 1939.60
        // NON_REFUNDABLE: none
        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-04
                rate_plan,reservations,amount
                STANDARD,2,1939.60
                NON_REFUNDABLE,0,0.00
                total,2,1939.60
                """, csv);
    }

    @Test
    void ratePlansIncludesBothPlans() {
        Reservation mayNonRefundable = book(101, "2027-05-10", "2027-05-12", RatePlan.NON_REFUNDABLE);
        Reservation mayStandard = book(102, "2027-05-15", "2027-05-16", RatePlan.STANDARD);
        service.confirm(mayNonRefundable.id());
        service.confirm(mayStandard.id());

        String csv = new RatePlanReport(store).generate(YearMonth.of(2027, 5));

        assertEquals("""
                Pousada Maré Alta,rate-plans,2027-05
                rate_plan,reservations,amount
                STANDARD,1,249.90
                NON_REFUNDABLE,1,424.83
                total,2,674.73
                """, csv);
    }
}

